#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

# Everything this wizard creates stays on this Mac, in a private folder, except
# the GitHub secrets. Secret values are never printed.
REPO_SLUG="bmichotte/sendbox"
WORKDIR="$HOME/.sendbox-signing"
ENV_FILE="$WORKDIR/wizard.env"   # only non-secret values, so re-runs remember them
OPENSSL=/usr/bin/openssl          # macOS LibreSSL: its .p12 files import with `security`
KEY="$WORKDIR/developer-id.key"
CSR="$WORKDIR/developer-id.csr"
CERT_PEM="$WORKDIR/developer-id.pem"
CA_PEM="$WORKDIR/DeveloperIDG2CA.pem"
P12="$WORKDIR/developer-id.p12"
IMPORTED_TO_LOGIN=no

# newest FILE matching a glob in ~/Downloads, or nothing.
newest_download() { ls -t "$HOME"/Downloads/$1 2>/dev/null | head -n1 || true; }

# new_key_and_csr: a fresh private key and certificate request. Apple refuses
# a request it already issued a certificate for, so each attempt needs both.
# An old key is moved aside, never deleted.
new_key_and_csr() {
  [[ -f "$KEY" ]] && mv "$KEY" "$KEY.$(date +%Y%m%d-%H%M%S).old"
  (umask 077 && "$OPENSSL" genrsa -out "$KEY" 2048 2>/dev/null)
  "$OPENSSL" req -new -key "$KEY" -out "$CSR" \
    -subj "/emailAddress=${APPLE_ACCOUNT_EMAIL}/CN=Sendbox Developer ID" 2>/dev/null
}

# random_password: 32 characters, never shown.
random_password() { "$OPENSSL" rand -base64 48 | tr -dc 'A-Za-z0-9' | head -c 32; }

banner "Sendbox · macOS signing and notarization (#14)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check prerequisites"
cd "$(git -C "$(dirname "${BASH_SOURCE[0]}")" rev-parse --show-toplevel)"
say "This sets up what the Release workflow needs to sign Sendbox with your"
say "Developer ID and notarize it with Apple, so the .dmg opens with no warning."
note "You need to be the Account Holder of the Apple Developer Program team."
[[ "$(uname)" == Darwin ]] || { warn "Run this on a Mac."; exit 1; }
for tool in "$OPENSSL" security curl base64; do
  command -v "$tool" >/dev/null 2>&1 || { warn "Missing tool: $tool"; exit 1; }
done
if ! gh auth status >/dev/null 2>&1; then
  warn "The GitHub CLI isn't logged in. Run: gh auth login, then run this wizard again."
  exit 1
fi
repo=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || true)
if [[ "$repo" != "$REPO_SLUG" ]]; then
  warn "gh points at '${repo:-nothing}', not $REPO_SLUG. Run this from the Sendbox clone."
  exit 1
fi
(umask 077 && mkdir -p "$WORKDIR")
chmod 700 "$WORKDIR"
say "${GREEN}✓${RESET} gh is logged in and targets $REPO_SLUG"
say "${GREEN}✓${RESET} private working folder: $WORKDIR"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create a private key and a certificate request"
say "Apple signs a certificate for a key that never leaves this Mac."
ask APPLE_ACCOUNT_EMAIL "Your Apple Developer account email (only goes into the request):"
write_env APPLE_ACCOUNT_EMAIL "$APPLE_ACCOUNT_EMAIL"
reuse=no
if [[ -f "$KEY" && -f "$CSR" ]]; then
  note "A key from a previous run exists. Reuse it only if Apple already issued your"
  note "Developer ID Application certificate for it; otherwise make a fresh one."
  confirm "Reuse the existing key?" && reuse=yes
fi
if [[ "$reuse" == yes ]]; then
  note "Reusing $KEY"
else
  new_key_and_csr
  say "${GREEN}✓${RESET} private key created: $KEY"
fi
say "${GREEN}✓${RESET} certificate request created: $CSR"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Developer ID Application certificate"
say "Create the certificate on the Apple Developer site, from that request."
open_url "https://developer.apple.com/account/resources/certificates/add"
open -R "$CSR" 2>/dev/null || true
step "Sign in as the Account Holder."
step "Under Software, select 'Developer ID Application', then Continue."
step "Profile Type: 'G2 Sub-CA (Xcode 11.4.1 or later)'."
step "Choose File → pick developer-id.csr (the Finder window that just opened) → Continue."
step "Click Download: developerID_application.cer lands in Downloads."
pause "Press Enter once it's downloaded"
key_mod=$("$OPENSSL" rsa -in "$KEY" -noout -modulus 2>/dev/null)
while :; do
  found=$(newest_download 'developerID_application*.cer')
  if [[ -n "$found" ]] && confirm "Use $found?"; then
    CER_PATH="$found"
  else
    ask CER_PATH "Path to the downloaded .cer file:"
  fi
  CER_PATH="${CER_PATH/#\~/$HOME}"
  cer_mod=$("$OPENSSL" x509 -inform DER -in "$CER_PATH" -noout -modulus 2>/dev/null || true)
  if [[ -z "$cer_mod" || "$key_mod" != "$cer_mod" ]]; then
    warn "That file isn't the certificate made from developer-id.csr."
    pause "Download the right one, then press Enter"
    continue
  fi
  cer_cn=$("$OPENSSL" x509 -inform DER -in "$CER_PATH" -noout -subject -nameopt RFC2253 \
    | sed -n 's/.*CN=\([^,]*\).*/\1/p')
  if [[ "$cer_cn" != "Developer ID Application:"* ]]; then
    warn "That is a '${cer_cn%%:*}' certificate; Sendbox needs 'Developer ID Application'."
    new_key_and_csr
    key_mod=$("$OPENSSL" rsa -in "$KEY" -noout -modulus 2>/dev/null)
    note "Apple won't take the same request twice, so here is a fresh developer-id.csr."
    open_url "https://developer.apple.com/account/resources/certificates/add"
    open -R "$CSR" 2>/dev/null || true
    step "Pick 'Developer ID Application' (not 'Developer ID Installer'), G2 Sub-CA."
    step "Upload the new developer-id.csr, then Download (developerID_application.cer)."
    pause "Press Enter once it's downloaded"
    continue
  fi
  break
done
write_env CER_PATH "$CER_PATH"
say "${GREEN}✓${RESET} the certificate matches your private key"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Package the certificate for CI"
"$OPENSSL" x509 -inform DER -in "$CER_PATH" -out "$CERT_PEM"
subject=$("$OPENSSL" x509 -in "$CERT_PEM" -noout -subject -nameopt RFC2253)
APPLE_SIGNING_IDENTITY=$(printf '%s' "$subject" | sed -n 's/.*CN=\([^,]*\).*/\1/p')
say "Signing identity: ${BOLD}${APPLE_SIGNING_IDENTITY}${RESET}"
if [[ "$APPLE_SIGNING_IDENTITY" != "Developer ID Application:"* ]]; then
  warn "This isn't a 'Developer ID Application' certificate. Create that type and re-run."
  exit 1
fi
write_env APPLE_SIGNING_IDENTITY "$APPLE_SIGNING_IDENTITY"
chain=()
if curl -fsSL "https://www.apple.com/certificateauthority/DeveloperIDG2CA.cer" \
     | "$OPENSSL" x509 -inform DER -out "$CA_PEM" 2>/dev/null; then
  chain=(-certfile "$CA_PEM")
  say "${GREEN}✓${RESET} included Apple's Developer ID G2 intermediate certificate"
else
  warn "Couldn't download Apple's intermediate certificate; packaging without it."
fi
APPLE_CERTIFICATE_PASSWORD=$(random_password)
CHECK_KEYCHAIN_PASSWORD=$(random_password)   # throwaway keychain only
export P12_PASS="$APPLE_CERTIFICATE_PASSWORD"
(umask 077 && "$OPENSSL" pkcs12 -export -inkey "$KEY" -in "$CERT_PEM" ${chain[@]+"${chain[@]}"} \
  -name "$APPLE_SIGNING_IDENTITY" -out "$P12" -passout env:P12_PASS \
  -certpbe PBE-SHA1-3DES -keypbe PBE-SHA1-3DES -macalg sha1)
# Check the .p12 imports the way the CI runner will, in a throwaway keychain.
test_kc="$WORKDIR/check.keychain-db"
security delete-keychain "$test_kc" >/dev/null 2>&1 || true
security create-keychain -p "$CHECK_KEYCHAIN_PASSWORD" "$test_kc" >/dev/null
security import "$P12" -k "$test_kc" -P "$APPLE_CERTIFICATE_PASSWORD" -T /usr/bin/codesign >/dev/null
identities=$(security find-identity -p codesigning "$test_kc" 2>/dev/null || true)
security delete-keychain "$test_kc" >/dev/null 2>&1 || true
if [[ "$identities" != *"$APPLE_SIGNING_IDENTITY"* ]]; then
  warn "The packaged certificate didn't import as a signing identity; stopping."
  exit 1
fi
APPLE_CERTIFICATE=$(base64 -i "$P12" | tr -d '\n')
say "${GREEN}✓${RESET} packaged and checked: it imports as a signing identity"
note "A random password protects the package; it goes straight to GitHub, never to the screen."
if confirm "Also add the certificate to your login keychain (recommended: keeps the private key safe and lets you sign locally)?"; then
  if security import "$P12" -k "$HOME/Library/Keychains/login.keychain-db" \
       -P "$APPLE_CERTIFICATE_PASSWORD" -T /usr/bin/codesign >/dev/null 2>&1; then
    say "${GREEN}✓${RESET} added to your login keychain"
  else
    note "Already in your login keychain (or Keychain refused): leaving it as is."
  fi
  IMPORTED_TO_LOGIN=yes
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "App Store Connect API key (notarization)"
say "CI notarizes with an API key, so no Apple ID password or 2FA is involved."
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Open the 'Team Keys' tab. First time? Click 'Request Access' and accept the terms."
step "Click 'Generate API Key' (or +). Name: 'Sendbox notarization'. Access: 'Developer'."
step "On the new row, click Download. Apple allows this only once: AuthKey_<KEY ID>.p8"
step "Above the table, copy the 'Issuer ID'."
pause "Press Enter once the .p8 is downloaded"
found=$(newest_download 'AuthKey_*.p8')
if [[ -n "$found" ]] && confirm "Use $found?"; then
  P8_PATH="$found"
else
  ask P8_PATH "Path to the downloaded AuthKey_….p8 file:"
fi
P8_PATH="${P8_PATH/#\~/$HOME}"
if ! head -n1 "$P8_PATH" 2>/dev/null | grep -q 'BEGIN PRIVATE KEY'; then
  warn "That file isn't an App Store Connect private key (.p8)."
  exit 1
fi
APPLE_API_PRIVATE_KEY=$(cat "$P8_PATH")
key_id=$(basename "$P8_PATH" | sed -n 's/^AuthKey_\([A-Z0-9]*\)\.p8$/\1/p')
if [[ -n "$key_id" ]] && confirm "Key ID is $key_id (from the file name)?"; then
  APPLE_API_KEY="$key_id"
else
  ask APPLE_API_KEY "Key ID (the 'Key ID' column):"
fi
until ask APPLE_API_ISSUER "Paste the Issuer ID:" \
  && [[ "$APPLE_API_ISSUER" =~ ^[0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12}$ ]]; do
  warn "An Issuer ID looks like 69a6de70-03db-47e3-e053-5b8c7c11a4d1."
done
write_env P8_PATH "$P8_PATH"
write_env APPLE_API_KEY "$APPLE_API_KEY"
write_env APPLE_API_ISSUER "$APPLE_API_ISSUER"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "GitHub secrets"
say "These go to $REPO_SLUG as Actions secrets (existing ones are replaced):"
for name in APPLE_CERTIFICATE APPLE_CERTIFICATE_PASSWORD APPLE_SIGNING_IDENTITY \
            APPLE_API_ISSUER APPLE_API_KEY APPLE_API_PRIVATE_KEY; do
  step "$name"
done
if confirm "Set them now?"; then
  set_secret APPLE_CERTIFICATE "$APPLE_CERTIFICATE"
  set_secret APPLE_CERTIFICATE_PASSWORD "$APPLE_CERTIFICATE_PASSWORD"
  set_secret APPLE_SIGNING_IDENTITY "$APPLE_SIGNING_IDENTITY"
  set_secret APPLE_API_ISSUER "$APPLE_API_ISSUER"
  set_secret APPLE_API_KEY "$APPLE_API_KEY"
  set_secret APPLE_API_PRIVATE_KEY "$APPLE_API_PRIVATE_KEY"
else
  SKIPPED+=("GitHub secrets: run this wizard again to set them")
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Tidy up"
unset P12_PASS
if [[ "$IMPORTED_TO_LOGIN" == yes ]]; then
  say "Your login keychain now holds the certificate and its private key."
  if confirm "Delete the working copies (key, request, package) in $WORKDIR?"; then
    rm -f "$KEY" "$CSR" "$CERT_PEM" "$CA_PEM" "$P12"
    say "${GREEN}✓${RESET} deleted"
  fi
else
  warn "$KEY is the only copy of your Developer ID private key."
  note "Keep $WORKDIR, or add the certificate to Keychain by re-running this wizard."
fi
say "The API key file can't be downloaded again. CI only needs the GitHub secret;"
say "if you lose the file, revoke the key in App Store Connect and re-run this wizard."
if confirm "Delete $P8_PATH from this Mac now?"; then
  rm -f "$P8_PATH"
  say "${GREEN}✓${RESET} deleted"
fi
say ""
say "Next: ask Claude to run the signing dry run (Release workflow, run by hand),"
say "then check the downloaded .dmg opens with no Gatekeeper warning."
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
